import React from 'react';
import { useParams, Link } from 'react-router-dom';
import Header from '../components/Header';
import PhotoGrid from '../components/PhotoGrid';
import projects from '../projects.json';
import './ProjectPage.css';

const ProjectPage = () => {
    const { projectId } = useParams();
    const project = projects.find((p) => p.id === projectId);

    if (!project) {
        return <div>Project not found</div>;
    }

    const images = project.images.map(imagePath => {
        try {
            // The path in the JSON should be relative to the `src` directory
            return require(`../${imagePath}`);
        } catch (err) {
            console.error(`Failed to load image: ${imagePath}. Please check the path in projects.json.`);
            return null;
        }
    }).filter(Boolean); // Filter out any nulls from failed imports

    return (
        <div>
            <Header />
            <div className="main-content">
                <div className="title-container">
                    <h1>{project.title}</h1>
                </div>
                <div className="text-container">
                    {project.long_description.split('\n\n').map((paragraph, index) => (
                        <p key={index}>{paragraph}</p>
                    ))}
                    <Link to="/projects">Back to Projects</Link>
                </div>
            </div>
            <div className="photo-grid-container">
                <PhotoGrid images={images} />
            </div>
        </div>
    );
};

export default ProjectPage;
