const FloatingEdge = ({
    id,
    source,
    target,
    style = {},
    markerEnd,
    }) => {
    const { getNode } = useReactFlow();

    const sourceNode = getNode(source);
    const targetNode = getNode(target);

    // Check for node existence and dimensions
    if (!sourceNode || !targetNode || !sourceNode.width || !sourceNode.height || !targetNode.width || !targetNode.height) {
        return null; // Return null if nodes or their dimensions are not yet available
    }

    const {
        sourcePoint,
        targetPoint,
        sourceHandlePosition,
        targetHandlePosition,
    } = getEdgeParams(sourceNode, targetNode);

    const [edgePath] = getSmoothStepPath({ // Changed to getSmoothStepPath
        sourceX: sourcePoint.x,
        sourceY: sourcePoint.y,
        sourcePosition: sourceHandlePosition,
        targetX: targetPoint.x,
        targetY: targetPoint.y,
        targetPosition: targetHandlePosition,
    });

    return (
        <g>
            <path
                id={id}
                className="react-flow__edge-path"
                d={edgePath}
                markerEnd={markerEnd}
                style={style}
            />
            <circle r="4" fill="var(--bright-text-color)">
                <animateMotion dur="4s" repeatCount="indefinite">
                    <mpath href={`#${id}`} />
                </animateMotion>
            </circle>
        </g>
    );
};

// Helper functions for floating edges
function getPointOnRect(x, y, rx, ry, rw, rh) {
    // calculate center point of rect
    const cx = rx + rw / 2;
    const cy = ry + rh / 2;

    // calculate vector from center to point
    const dx = x - cx;
    const dy = y - cy;

    // calculate angle of vector
    const angle = Math.atan2(dy, dx);

    // calculate distance from center to side of rect
    const halfWidth = rw / 2;
    const halfHeight = rh / 2;

    // calculate x and y coords
    let x2 = cx + halfWidth * Math.cos(angle);
    let y2 = cy + halfHeight * Math.sin(angle);

    if (Math.abs(dx) * halfHeight > Math.abs(dy) * halfWidth) {
        // hit vertical side
        x2 = cx + (dx > 0 ? halfWidth : -halfWidth);
        y2 = cy + (dy * halfWidth) / Math.abs(dx);
    } else {
        // hit horizontal side
        x2 = cx + (dx * halfHeight) / Math.abs(dy);
        y2 = cy + (dy > 0 ? halfHeight : -halfHeight);
    }

    return { x: x2, y: y2 };
}

function getEdgeParams(sourceNode, targetNode) {
    const sourcePoint = {
        x: sourceNode.position.x + sourceNode.width / 2,
        y: sourceNode.position.y + sourceNode.height / 2,
    };
    const targetPoint = {
        x: targetNode.position.x + targetNode.width / 2,
        y: targetNode.position.y + targetNode.height / 2,
    };

    const sourceIntersectionPoint = getPointOnRect(
        targetPoint.x,
        targetPoint.y,
        sourceNode.position.x,
        sourceNode.position.y,
        sourceNode.width,
        sourceNode.height
    );

    const targetIntersectionPoint = getPointOnRect(
        sourcePoint.x,
        sourcePoint.y,
        targetNode.position.x,
        targetNode.position.y,
        targetNode.width,
        targetNode.height
    );

    const sourceHandlePosition = getHandlePosition(sourceNode, sourceIntersectionPoint);
    const targetHandlePosition = getHandlePosition(targetNode, targetIntersectionPoint);

    return {
        sourceNode,
        targetNode,
        sourcePoint: sourceIntersectionPoint,
        targetPoint: targetIntersectionPoint,
        sourceHandlePosition,
        targetHandlePosition,
    };
}

function getHandlePosition(node, intersectionPoint) {
    const x = intersectionPoint.x - (node.position.x + node.width / 2);
    const y = intersectionPoint.y - (node.position.y + node.height / 2);

    if (Math.abs(x) > Math.abs(y)) {
        return x > 0 ? Position.Right : Position.Left;
    }

    return y > 0 ? Position.Bottom : Position.Top;
}

