function ConceptGraph() {
    const { fitView } = useReactFlow();
    const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
    const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

    // Add state for selected node
    const [selectedNode, setSelectedNode] = useState(null);

    // Handle node click
    const onNodeClick = useCallback((event, node) => {
        setSelectedNode(node);
    }, []);

    // Handle pane click to close description
    const onPaneClick = useCallback(() => {
        setSelectedNode(null);
    }, []);

    // Apply layout on mount
    useEffect(() => {
        const { nodes: layoutedNodes, edges: layoutedEdges } = getLayoutedElements(
            nodes,
            edges
        );

        setNodes(layoutedNodes);
        setEdges(layoutedEdges);

        // Fit view after layout is applied
        // Use a timeout to ensure React Flow has rendered the nodes with new positions
        setTimeout(() => {
            fitView();
        }, 100);

    }, []); // Run once on mount

    return (
        <div style={{ height: '100vh', width: '100%' }}>
            <GraphLegend groupColors={GROUP_COLORS} />
            <ReactFlow colorMode="dark"
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                nodeTypes={nodeTypes}
                edgeTypes={edgeTypes}
                onNodeClick={onNodeClick} // Add node click handler
                onPaneClick={onPaneClick} // Add pane click handler
            >
                <Background />
                <Controls />
                <MiniMap />
            </ReactFlow>

            {/* Conditionally render the NodeDescriptionPanel */}
            <AnimatePresence> {/* Wrap with AnimatePresence */}
                {selectedNode && (
                    <NodeDescriptionPanel nodeData={selectedNode.data} onClose={onPaneClick} />
                )}
            </AnimatePresence>
        </div>
    );
}

