import React from 'react';
import './GraphLegend.css';

const GraphLegend = ({ groupColors }) => {
    return (
        <div className="graph-legend">
            <h3>URBAN 200 - KB</h3>
            <div className="color-key">
                {Object.entries(groupColors).map(([groupName, color]) => (
                    <div key={groupName} className="key-item">
                        <span className="key-color-box" style={{ backgroundColor: color }}></span>
                        <span className="key-label">{groupName}</span>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default GraphLegend;